using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // Preserve EF Core 8 discriminator property name for existing documents.
            // EF Core 9 defaults to "$type"; existing 500K docs use "Discriminator".
            entity.HasDiscriminator<string>("Discriminator");

            // Preserve EF Core 8 compound id format ("Product|123") for existing documents.
            // EF Core 9 defaults to key-only ids; existing docs use the old format.
            entity.HasRootDiscriminatorInJsonId(true);
        });

        // HasIndex removed — Cosmos DB provider now throws at startup.
        // Manage indexing via the container's indexing policy (Azure Portal/Bicep).
    }
}
